<script setup>
import { ref, computed, onMounted } from 'vue'
const { databaseEnabled, lastError, loadCurrentRound, loadRounds, saveBetToDatabase, settleBetInDatabase, createInitialChallenge, createRound, deleteChallenge } = useChallengeData()
const round = ref({ id: null, week: 1, title: 'Your first challenge', dates: 'No round created yet', bets: [] })
const previousRounds = ref([])
const bet = ref({ id: null, bettorId: null, type: 'Accumulator', stake: 20, status: 'pending', selections: [] })
const legs = ref([{ match: '', market: 'Match result', pick: '', odds: 1.5, status: 'pending' }]); const stake = ref(20); const odds = ref(1); const modal = ref(false); const settlementModal = ref(false); const newChallengeModal = ref(false); const settlementLegs = ref([]); const showSlip = ref(false); const loading = ref(false); const toast = ref(''); const newChallenge = ref({ title: '', bettor: 'me', stake: 20, deadline: '' })
const combinedOdds = computed(() => legs.value.reduce((total, leg) => total * (Number(leg.odds) || 1), 1)); const potentialReturn = computed(() => stake.value * combinedOdds.value); const totalStaked = computed(() => round.value.bets.reduce((sum, item) => sum + Number(item.stake || 0), 0)); const settled = computed(() => ['won', 'lost'].includes(bet.value.status)); const profit = computed(() => settled.value ? Number(bet.value.actualReturn || 0) - Number(bet.value.stake || 0) : 0); const money = value => `€ ${Number(value || 0).toFixed(2)}`; const notify = message => { toast.value = message; window.setTimeout(() => toast.value = '', 3500) }
function applyRound(value) { if (!value) return; round.value = value; if (value.bets?.[0]) { bet.value = value.bets[0]; stake.value = bet.value.stake; legs.value = bet.value.selections.map(item => ({ match: item.match || item.matchId || '', market: item.market, pick: item.pick, odds: item.odds, status: item.status || 'pending' })) } }
async function saveBet() { loading.value = true; bet.value = { ...bet.value, stake: stake.value, selections: legs.value.map((leg, i) => ({ id: bet.value.selections[i]?.id || `leg-${i}`, matchId: leg.match, market: leg.market, pick: leg.pick, odds: Number(leg.odds), status: 'pending' })) }; round.value = { ...round.value, bets: [bet.value] }; const saved = await saveBetToDatabase({ roundId: round.value.id, bettorId: bet.value.bettorId, bet: bet.value, legs: legs.value, matches: [] }); modal.value = false; loading.value = false; notify(saved ? 'Bet saved.' : `Could not save: ${lastError.value}`) }
function openSettlement() { settlementLegs.value = legs.value.map((leg, i) => ({ ...leg, id: bet.value.selections[i]?.id, status: bet.value.selections[i]?.status || 'pending' })); settlementModal.value = true }
async function settleBet() { const result = await settleBetInDatabase({ betId: bet.value.id, selectionStatuses: settlementLegs.value, stake: stake.value, combinedOdds: combinedOdds.value }); if (!result) { notify(`Could not settle: ${lastError.value}`); return }; bet.value = { ...bet.value, status: result.status, actualReturn: result.actualReturn, selections: bet.value.selections.map((item, i) => ({ ...item, status: settlementLegs.value[i].status })) }; legs.value = legs.value.map((leg, i) => ({ ...leg, status: settlementLegs.value[i].status })); round.value = { ...round.value, bets: [bet.value] }; settlementModal.value = false; notify(`Bet settled as ${result.status}.`) }
async function addNewChallenge() { loading.value = true; const value = await createRound({ challengeId: round.value.challengeId, week: round.value.week + 1, title: newChallenge.value.title || `Week ${round.value.week + 1} challenge`, bettorId: round.value.bettorId, stake: Number(newChallenge.value.stake) || 20, deadline: newChallenge.value.deadline ? new Date(newChallenge.value.deadline).toISOString() : new Date(Date.now() + 7 * 86400000).toISOString() }); if (value) { previousRounds.value.unshift(round.value); round.value = value; bet.value = { id: null, bettorId: value.bettorId, type: 'Accumulator', stake: value.stake, status: 'pending', selections: [] }; stake.value = value.stake; legs.value = [{ match: '', market: 'Match result', pick: '', odds: 1.5, status: 'pending' }]; newChallengeModal.value = false; notify('New challenge created.') } else notify(`Could not create challenge: ${lastError.value}`); loading.value = false }
async function removeCurrentChallenge() { if (!window.confirm('Delete this challenge and all of its rounds, bets, and selections? This cannot be undone.')) return; const deleted = await deleteChallenge(round.value.challengeId); if (deleted) { window.location.href = '/'; } else notify(`Could not delete challenge: ${lastError.value}`) }
onMounted(async () => { if (!databaseEnabled.value) return; let rounds = await loadRounds(); let value = rounds[0]; if (!value) value = await createInitialChallenge(); if (value) { applyRound(value); previousRounds.value = rounds.slice(1) } })
</script>
<template>
<NuxtLink class="account-avatar-link" to="/account">ME</NuxtLink>
<NuxtLink class="account-nav-link" to="/account">♙ <span>Account</span></NuxtLink>
<NuxtLink class="challenge-admin-link" to="/challenges">Manage challenges</NuxtLink>
<div class="quick-actions"><button class="outline-button" @click="newChallengeModal=true">＋ New challenge</button><button class="outline-button danger-button" @click="removeCurrentChallenge">Delete challenge</button><button v-if="bet.selections.length" class="primary-button" @click="openSettlement">{{ settled ? 'Edit result' : 'Settle bet' }} →</button></div>
<section class="history-strip" v-if="previousRounds.length"><div class="history-strip-heading"><p class="overline">RECENT ACTIVITY</p><h2>Past weeks</h2></div><div class="history-strip-list"><div v-for="item in previousRounds" :key="item.id" class="past-row"><div class="week-number">{{ item.week }}</div><div class="past-main"><strong>{{ item.title }}</strong><small>{{ item.dates }}</small></div><div class="past-result"><span class="result-pill" :class="item.bets[0]?.status || 'waiting'">{{ item.bets[0]?.status || 'No bet' }}</span><strong>{{ item.bets[0]?.actualReturn == null ? '—' : money(Number(item.bets[0].actualReturn) - Number(item.bets[0].stake)) }}</strong></div></div></div></section>
<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark"><span/><span/></div><div><strong>double<span>chance</span></strong><small>challenge tracker</small></div></div><div class="side-label">Workspace</div><nav class="main-nav"><NuxtLink class="nav-item active" to="/">▦ <span>Overview</span></NuxtLink><NuxtLink class="nav-item" to="/admin">♙ <span>Manage players</span></NuxtLink></nav><div class="side-spacer"/><div class="next-turn-card"><div class="eyebrow">✦ Next up</div><div class="turn-person"><div class="avatar yellow">FR</div><div><strong>Friend's turn</strong><small>Next round · €20 default stake</small></div></div></div></aside><main class="main-content"><header class="topbar"><div class="breadcrumbs"><span>My challenge</span><b>/</b><strong>Overview</strong></div><div class="top-actions"><span class="sync-status"><i class="live-dot"/>{{ databaseEnabled ? 'Supabase connected' : 'Database not connected' }}</span><NuxtLink class="avatar purple" to="/admin">ME</NuxtLink></div></header><div class="page-wrap"><section class="welcome-row"><div><p class="overline">YOUR FOOTBALL CHALLENGE</p><h1>Welcome back <span>✦</span></h1><p class="subheading">One bettor, one bet, every week.</p></div><button class="primary-button" @click="modal=true">＋ {{ bet.selections.length ? 'Edit bet' : 'Add this week’s bet' }}</button></section><section class="stats-grid"><article class="stat-card dark-card"><div class="stat-top"><span>Total staked</span></div><strong class="big-number">{{ money(totalStaked) }}</strong><div class="stat-foot"><span>Current round</span></div></article><article class="stat-card"><div class="stat-top"><span>Record</span></div><strong class="big-number">{{ settled && bet.status === 'won' ? '1 / 0' : settled ? '0 / 1' : '0 / 0' }}</strong><div class="stat-foot"><span>Settled bets</span></div></article><article class="stat-card"><div class="stat-top"><span>Best return</span></div><strong class="big-number">{{ settled && bet.status === 'won' ? money(bet.actualReturn) : money(0) }}</strong><div class="stat-foot"><span>Settled returns</span></div></article><article class="stat-card"><div class="stat-top"><span>Next turn</span></div><strong class="big-number">Friend</strong><div class="stat-foot"><span>After this round</span></div></article></section><section class="content-grid"><div class="left-column"><div class="section-heading"><div><p class="overline">THE CURRENT ROUND</p><h2>Week {{ round.week }} <span class="badge">{{ round.id ? 'In progress' : 'Not started' }}</span></h2></div><button class="text-button" @click="modal=true">Edit bet →</button></div><article class="challenge-card"><div class="challenge-head"><div><span class="week-kicker">{{ round.dates }}</span><h3>{{ round.title }}</h3></div><div class="stake-pill"><span>Stake</span><strong>{{ money(stake) }}</strong></div></div><div class="player-bets"><div class="player-bet"><div class="person-line"><div class="avatar purple">ME</div><div><strong>This week's bet</strong><small>{{ bet.selections.length ? `${bet.type} · ${bet.selections.length} selections` : 'Not placed yet' }}</small></div><span class="bet-state" :class="bet.status">{{ bet.selections.length ? bet.status : 'Waiting' }}</span></div><button class="bet-link" @click="showSlip=!showSlip">{{ showSlip ? 'Hide slip ↑' : 'View slip ↗' }}</button></div></div><div v-if="showSlip && bet.selections.length" class="bet-slip"><div class="bet-slip-heading"><h3>{{ bet.type }} <span>{{ bet.selections.length }} legs</span></h3><button v-if="!settled" class="primary-button" @click="openSettlement">Settle bet</button></div><div class="slip-legs"><div v-for="(leg,i) in legs" :key="i" class="slip-leg"><div class="slip-leg-number">{{ i+1 }}</div><div class="slip-leg-main"><strong>{{ leg.match }}</strong><small>{{ leg.market }} · {{ leg.pick }}</small></div><strong>{{ Number(leg.odds).toFixed(2) }}</strong><span class="slip-status" :class="leg.status">{{ leg.status }}</span></div></div></div></article><div class="section-heading lower-heading"><div><p class="overline">RECENT ACTIVITY</p><h2>Past weeks</h2></div></div><div class="past-weeks"><div v-if="settled" class="past-row"><div class="week-number">{{ round.week }}</div><div class="past-main"><strong>{{ round.title }}</strong><small>{{ bet.status === 'won' ? 'Bet won' : 'Bet lost' }}</small></div><div class="past-result"><span class="result-pill" :class="bet.status">{{ bet.status }}</span><strong>{{ money(profit) }}</strong></div></div><div v-else class="empty-state"><strong>No settled weeks yet</strong><span>Completed rounds will appear here.</span></div></div></div><div class="right-column"><div class="section-heading"><div><p class="overline">THE SCOREBOARD</p><h2>Challenge leaders</h2></div></div><article class="leaderboard"><div class="leader-row"><div class="leader-person"><span class="rank">1</span><div class="avatar purple">ME</div><strong>You</strong></div><strong>{{ settled && bet.status === 'won' ? '1 - 0' : settled ? '0 - 1' : '0 - 0' }}</strong><span class="profit">{{ money(profit) }}</span></div></article></div></section></div></main><div v-if="toast" class="toast">✓ {{ toast }}</div></div>
<div v-if="modal" class="modal-backdrop"><section class="modal"><button class="modal-close" @click="modal=false">×</button><h2>{{ bet.selections.length ? 'Edit your bet' : 'Add your bet' }}</h2><form @submit.prevent="saveBet"><label>Stake (€)<input v-model.number="stake" type="number" min="1"/></label><div class="legs-editor"><div class="legs-heading"><strong>Accumulator legs</strong><button type="button" class="outline-button" @click="legs.push({match:'',market:'Match result',pick:'',odds:1.5,status:'pending'})">＋ Add leg</button></div><div v-for="(leg,i) in legs" :key="i" class="leg-row"><div class="leg-number">{{ i+1 }}</div><div class="leg-fields"><input v-model="leg.match" placeholder="Match"/><div class="leg-subfields"><select v-model="leg.market"><option>Match result</option><option>Both teams to score</option><option>Total goals</option></select><input v-model="leg.pick" placeholder="Pick"/><input v-model.number="leg.odds" type="number" step=".01"/></div></div></div></div><button class="primary-button full-width">Save bet →</button></form></section></div>
<div v-if="settlementModal" class="modal-backdrop"><section class="modal"><button class="modal-close" @click="settlementModal=false">×</button><p class="overline">SETTLE BET</p><h2>Confirm results</h2><div class="settlement-list"><label v-for="(leg,i) in settlementLegs" :key="i">{{ leg.match || `Leg ${i+1}` }}<select v-model="leg.status"><option value="pending">Pending</option><option value="won">Won</option><option value="lost">Lost</option></select></label></div><button class="primary-button full-width" @click="settleBet">Save settlement →</button></section></div>
<div v-if="newChallengeModal" class="modal-backdrop"><section class="modal"><button class="modal-close" @click="newChallengeModal=false">×</button><p class="overline">NEXT ROUND</p><h2>New challenge</h2><p class="modal-intro">Set up the next weekly turn.</p><label>Title<input v-model="newChallenge.title" placeholder="Weekend challenge" /></label><label>Stake (€)<input v-model.number="newChallenge.stake" type="number" min="1" /></label><label>Deadline<input v-model="newChallenge.deadline" type="datetime-local" /></label><button class="primary-button full-width" :disabled="loading" @click="addNewChallenge">{{ loading ? 'Creating…' : 'Create challenge →' }}</button></section></div>
</template>
